package solution
func DecodeFrames(data []byte)([][]byte,bool){
    if len(data) == 0 {
        return [][]byte{}, true
    }

    var result [][]byte
    var offset int
    var totalPayload int
    var checksum int

    for i := 0; i < len(data); {
        if i+1 >= len(data) {
            // Truncation detected: not enough bytes for length byte
            return result, false
        }

        length := int(data[i])
        if length < 0 || length > 255 {
            // Invalid byte value for length
            return result, false
        }

        if i+1+1 >= len(data) {
            // Truncation detected: not enough bytes for payload and checksum
            return result, false
        }

        payload := make([]byte, length)
        copy(payload, data[i+1:i+1+length])

        if len(payload) != length {
            // Payload length mismatch
            return result, false
        }

        checksum := int(data[i+1+length])
        if checksum < 0 || checksum > 255 {
            // Invalid byte value for checksum
            return result, false
        }

        totalPayload += length
        i += 1 + length + 1
        result = append(result, payload)
    }

    // Checksum validation: must equal sum of all payload bytes modulo 256
    expectedChecksum := totalPayload % 256
    if checksum != expectedChecksum {
        return result, false
    }

    return result, true
}

